            var columnIndex = Array.IndexOf(columns, column);
            var columnTasks = FilteredTasksForColumn(column);

            <KanbanColumn ColumnName="@column"
                          Tasks="columnTasks"
                          CanMoveLeft="columnIndex > 0"
                          CanMoveRight="columnIndex < columns.Length - 1"
                          OnMoveLeft="id => MoveTaskAsync(id, columns[columnIndex - 1])"
                          OnMoveRight="id => MoveTaskAsync(id, columns[columnIndex + 1])"
                          OnTaskCreated="HandleTaskCreated" />
        }
    </div>
}

